"lovelace-background": "radial-gradient(900px 600px at 12% -8%, var(--ng-amb-1, rgba(var(--rgb-ng-acc), 0.10)), transparent 60%), radial-gradient(700px 520px at 96% 8%, var(--ng-amb-2, rgba(var(--rgb-ng-acc-2), 0.07)), transparent 62%), radial-gradient(900px 700px at 50% 120%, var(--ng-amb-3, rgba(var(--rgb-ng-acc-3), 0.08)), transparent 60%), radial-gradient(1300px 900px at 88% -25%, var(--ng-amb-4, rgba(0, 0, 0, 0)), transparent 65%), radial-gradient(120% 90% at 50% 0%, rgba(var(--rgb-ng-bg), 0) 55%, var(--ng-bg) 125%), linear-gradient(rgba(var(--rgb-ng-acc-3), 0.07) 1px, transparent 1px) 0 0 / 48px 48px, linear-gradient(90deg, rgba(var(--rgb-ng-acc-3), 0.07) 1px, transparent 1px) 0 0 / 48px 48px, var(--ng-bg) fixed",
"app-header-background-color": "rgba(255, 255, 255, 0.72)",
