      pile.parts.push({ x, y, vx: Math.cos(a) * v * (gold ? 0.4 : 1), vy: -Math.abs(Math.sin(a)) * v, r: gold ? 1 + Math.random() * 2 : 1.5 + Math.random() * 2.5, life: 0.5 + Math.random() * 0.7, gold });
